output:
echo -e 'location ~ \.php$ {
  fastcgi_cache wordpress;
  fastcgi_cache_valid 200 60m;
  fastcgi_cache_use_stale updating error timeout;
  fastcgi_cache_key "$scheme$request_method$host$request_uri";
}' >> /etc/nginx/sites-available/wordpress && nginx -s reload

echo -e 'stream {
  upstream mysql_backend {
    server 192.168.1.10:3306;
    server 192.168.1.11:3306;
  }
  server {
    listen 3306;
    proxy_pass mysql_backend;
  }
}' >> /etc/nginx/nginx.conf && nginx -s reload

echo -e 'server {
  listen 80 http2;
  location / {
    grpc_pass grpc://grpc_backend:50051;
  }
}' >> /etc/nginx/sites-available/grpc && nginx -s reload

echo -e 'server {
  listen 443 ssl;
  ssl_certificate /etc/ssl/certs/server.crt;
  ssl_certificate_key /etc/ssl/private/server.key;
  location /ws {
    proxy_pass https://websocket-server;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
  }
}' >> /etc/nginx/sites-available/default && nginx -s reload

echo -e 'server {
  listen 127.0.0.1:8080;
  location /nginx_status {
    stub_status on;
    allow 127.0.0.1;
    deny all;
  }
}' > /etc/nginx/sites-available/status && ln -sf /etc/nginx/sites-available/status /etc/nginx/sites-enabled/ && nginx -s reload
